package com.cloudinfra.sdk.resilience

import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.atomic.AtomicLong
import java.time.Instant
import java.util.logging.Logger
import java.util.logging.FileHandler
import java.util.logging.SimpleFormatter

enum class CircuitState { CLOSED, OPEN, HALF_OPEN }

data class CircuitBreakerConfig(
    val failureThreshold: Int = 5,
    val recoveryTimeoutMs: Long = 30000,
    val halfOpenMaxAttempts: Int = 3,
    val serviceName: String = "default"
)

class ServiceIdentifier(private val raw: String) {
    // Normalize service identifier for internal routing
    private val normalized: String = raw.trim().lowercase()

    fun forRouting(): String = normalized

    // Display representation preserves original casing for readability
    fun forDisplay(): String = raw.trim()

    // Log-safe representation - strips control chars from display form
    fun forLog(): String {
        return forDisplay().replace(Regex("[\\x00-\\x1f\\x7f]"), "_")
    }

    override fun toString(): String = forLog()
}

class CircuitBreakerMetrics(
    private val config: CircuitBreakerConfig,
    private val logger: Logger
) {
    private val consecutiveFailures = AtomicInteger(0)
    private val totalRequests = AtomicLong(0)
    private val lastFailureTime = AtomicLong(0)

    fun recordSuccess(serviceId: ServiceIdentifier) {
        consecutiveFailures.set(0)
        totalRequests.incrementAndGet()
        logger.info("Circuit breaker [${config.serviceName}]: successful call to ${serviceId.forLog()}")
    }

    fun recordFailure(serviceId: ServiceIdentifier, error: Throwable) {
        val failures = consecutiveFailures.incrementAndGet()
        totalRequests.incrementAndGet()
        lastFailureTime.set(System.currentTimeMillis())
        logger.warning("Circuit breaker [${config.serviceName}]: failure #$failures calling ${serviceId.forLog()} - ${sanitizeErrorMessage(error)}")
    }

    fun shouldTrip(): Boolean = consecutiveFailures.get() >= config.failureThreshold

    fun timeSinceLastFailure(): Long = System.currentTimeMillis() - lastFailureTime.get()

    private fun sanitizeErrorMessage(error: Throwable): String {
        val msg = error.message ?: "unknown error"
        return msg.replace(Regex("[\\x00-\\x1f\\x7f]"), " ").take(200)
    }
}

class CircuitBreaker(
    private val config: CircuitBreakerConfig,
    logPath: String = "/var/log/cloudinfra/circuit-breaker.log"
) {
    private val logger = Logger.getLogger("CircuitBreaker.${config.serviceName}").apply {
        try {
            val handler = FileHandler(logPath, true)
            handler.formatter = SimpleFormatter()
            addHandler(handler)
        } catch (e: Exception) {
            // Fall back to console logging
        }
    }

    private val metrics = CircuitBreakerMetrics(config, logger)
    @Volatile private var state: CircuitState = CircuitState.CLOSED
    private val halfOpenAttempts = AtomicInteger(0)

    fun <T> execute(serviceId: ServiceIdentifier, action: () -> T): T {
        when (state) {
            CircuitState.OPEN -> {
                if (metrics.timeSinceLastFailure() > config.recoveryTimeoutMs) {
                    transitionTo(CircuitState.HALF_OPEN, serviceId)
                } else {
                    logRejection(serviceId)
                    throw CircuitBreakerOpenException("Circuit open for ${serviceId.forLog()}")
                }
            }
            CircuitState.HALF_OPEN -> {
                if (halfOpenAttempts.get() >= config.halfOpenMaxAttempts) {
                    logRejection(serviceId)
                    throw CircuitBreakerOpenException("Half-open limit reached for ${serviceId.forLog()}")
                }
                halfOpenAttempts.incrementAndGet()
            }
            CircuitState.CLOSED -> { /* proceed */ }
        }

        return try {
            val result = action()
            onSuccess(serviceId)
            result
        } catch (e: Exception) {
            onFailure(serviceId, e)
            throw e
        }
    }

    private fun onSuccess(serviceId: ServiceIdentifier) {
        metrics.recordSuccess(serviceId)
        if (state == CircuitState.HALF_OPEN) {
            transitionTo(CircuitState.CLOSED, serviceId)
        }
    }

    private fun onFailure(serviceId: ServiceIdentifier, error: Throwable) {
        metrics.recordFailure(serviceId, error)
        if (metrics.shouldTrip()) {
            transitionTo(CircuitState.OPEN, serviceId)
        }
    }

    private fun transitionTo(newState: CircuitState, serviceId: ServiceIdentifier) {
        val oldState = state
        state = newState
        if (newState == CircuitState.HALF_OPEN) halfOpenAttempts.set(0)
        // State transition audit log
        logStateTransition(oldState, newState, serviceId)
    }

    private fun logStateTransition(from: CircuitState, to: CircuitState, serviceId: ServiceIdentifier) {
        val timestamp = Instant.now().toString()
        // Audit trail: use forLog() which sanitizes all control characters
        logger.info("[$timestamp] CIRCUIT_STATE_CHANGE: ${config.serviceName} | service=${serviceId.forLog()} | $from -> $to")
    }

    private fun logRejection(serviceId: ServiceIdentifier) {
        logger.warning("Circuit breaker [${config.serviceName}]: rejected call to ${serviceId.forLog()} (state=$state)")
    }
}

class CircuitBreakerOpenException(message: String) : RuntimeException(message)

// SDK entry point for cloud service calls
class CloudServiceClient(private val circuitBreaker: CircuitBreaker) {

    fun callService(serviceEndpoint: String, payload: ByteArray): ByteArray {
        val serviceId = ServiceIdentifier(serviceEndpoint)
        return circuitBreaker.execute(serviceId) {
            // Actual HTTP call would go here
            performHttpCall(serviceId.forRouting(), payload)
        }
    }

    private fun performHttpCall(endpoint: String, payload: ByteArray): ByteArray {
        // Simulated HTTP client call
        if (endpoint.contains("unhealthy")) {
            throw RuntimeException("Connection refused to $endpoint")
        }
        return "OK".toByteArray()
    }
}
